"""Install the Cannon Fodder in-game level editor for WHDLoad from your own
disk images, and copy missions between installs.

    python3 patch.py "Disk 1.adf" "Disk 2.adf" "Disk 3.adf" [--output CannonFodder]
    python3 patch.py list CannonFodder/Custom
    python3 patch.py export CannonFodder/Custom 0123abcd.cmi --output MyMission
    python3 patch.py import CannonFodder/Custom MyMission [--new-id]

Only the Python 3 standard library is needed. The disk images are only read.
Every file written is new and is read back before success is reported.
"""
